      "body": "________________________________________\n※このメールは、旧「NHKプラス」にご登録されていて、2026年3月24日時点で「NHK ONE」へのアカウント移行がお済みでない方にお送りしています。\n（このメールは送信専用アドレスからお送りしているため、返信はできません）\n________________________________________\n\nいつもNHKをご利用いただき、誠にありがとうございます。\n\nお客様にご利用いただいていた旧「NHKプラス」は、昨年9月30日をもってサービスを終了し、10月1日からは新たなインターネットサービス 「NHK ONE」 としてサービスを開始いたしました。\n「NHK ONE」では、これまでと同様にパソコンやスマートフォンで番組をご覧いただけるほか、ニュース記事を読むなど、より幅広いサービスを提供しています。\nお客様はすでに受信契約をされておりますので、別途のご契約や追加のご負担の必要なく「NHK ONE」をご利用いただけます。ぜひ移行手続きをして、ご利用いただけますと幸いです。\n＜「NHK ONE」でご利用いただけるサービスについて詳しくはこちら＞\nhttps://www.nhk.or.jp/nhkone/service/\n\n■「NHK ONE」のご利用には「NHK ONEアカウント」への移行手続きが必要です\n\n旧NHKプラスをご利用いただいていたお客様には、簡単にお手続きいただける 「アカウント移行手続き」をご用意しています。（移行期間は2026年9月30日までです）\n移行手続きには、旧NHKプラスにご登録いただいていたこのメールが届いているメールアドレスを使用します。アドレスの変更をご希望の場合は、移行手続きを完了していただいたのち、NHK ONEアカウント設定ページから変更いただけます。\n所要時間は5〜10分程度です。\nぜひこの移行期間内に、お早めに移行手続きをいただけますと幸いです。\n＜移行のお手続きはこちらから>\nhttps://portal.web.nhk/kakunin\n\nすでに移行手続きがお済みの場合は、行き違いのご連絡となりましたことをお詫び申し上げます。\n今後ともNHKへのご理解とご協力を賜りますよう、よろしくお願い申し上げます。\n\n※移行手続き前に受信契約を解約された方にも、このメールが配信される場合がございます。あらかじめご了承ください。\n※NHKを名乗る不審なメールが増えておりますので、ご注意ください。\n────────────────────────────────\n◆手続き方法について（動画や画像でわかりやすくご紹介しています）\nhttps://www.nhk.or.jp/nhkone/how-to-use/article/P001-0001/\n────────────────────────────────\n◆「NHK ONE」に関する「よくあるご質問」\nhttps://www.nhk.or.jp/nhkone/help/\n────────────────────────────────\n◆このメールについてのお問い合わせはこちらへ\n電話番号: 0570-099-033 （ナビダイヤル）\n自動音声ガイダンスで「1」を押してください。\n----------------------------------------------------------------------\n午前9時～午後6時（土・日・祝日も受付）\n────────────────────────────────\n",
