      "title": "【第2弾】2026/5/13～6/17の平日",
      "subject": "",
      "body": "────────────────────────────────\n※このメールは、旧NHKプラスにご登録されていて、2026年5月12日時点で「NHK ONE」へのアカウント移行がお済みでない方に、送信専用アドレスからお送りしています。すでに移行済の場合、行き違いのご連絡となりましたことをお詫び申し上げます。\n────────────────────────────────\n \nいつもNHKをご利用いただき、誠にありがとうございます。\n \n繰り返しのご案内となり大変恐縮ですが、お客様にご利用いただいていた旧NHKプラスは、昨年9月30日をもってサービスを終了し、10月1日から新たなインターネットサービス 「NHK ONE」 を開始いたしました。\n \nNHK ONEでは、「朝ドラ」「大河ドラマ」をはじめ様々な番組やニュースをパソコンやスマートフォンでご覧いただけます。まもなく開幕するサッカーのワールドカップ（6月12日開幕）も「NHK ONE」でお楽しみいただけます。\n \nお客様はすでに受信契約をされておりますので、別途のご契約や追加のご負担の必要なく「NHK ONE」をご利用いただけます。ぜひ移行手続きをして、ご利用いただけますと幸いです。\n \n＜「NHK ONE」でご利用いただけるサービスについて詳しくはこちら＞\nhttps://www.nhk.or.jp/nhkone/service/\n \n■「NHK ONE」のご利用には「NHK ONEアカウント」への移行手続きが必要です\n \n旧NHKプラスをご利用いただいていたお客様には、簡単にお手続きいただける 「アカウント移行手続き」をご用意しています（移行期限は2026年9月30日までです）。\n \n移行手続きには、旧NHKプラスにご登録いただいていたこのメールを受信されたメールアドレスを移行手続きにご使用いただきます。\n（使用するメールアドレスの変更をご希望の場合は、移行手続きを完了後にNHK ONEアカウント設定ページから変更いただけます）\n \n所要時間は5～10分程度です。\n移行期限は2026年9月30日までです。お早めにお手続きいただきますようお願いいたします。\n \n＜移行のお手続きはこちらから>\nhttps://portal.web.nhk/kakunin\n \nすでに移行手続きがお済みの場合は、行き違いのご連絡となりましたことをお詫び申し上げます。\n今後ともNHKへのご理解とご協力を賜りますよう、よろしくお願い申し上げます。\n \n※移行手続き前に受信契約を解約された方にも、このメールが配信される場合がございます。あらかじめご了承ください。\n※NHKを名乗る不審なメールが増えておりますので、ご注意ください。\n────────────────────────────────\n◆手続き方法について（動画や画像でわかりやすくご紹介しています）\nhttps://www.nhk.or.jp/nhkone/how-to-use/article/P001-0001/\n────────────────────────────────\n◆「NHK ONE」に関する「よくあるご質問」\nhttps://www.nhk.or.jp/nhkone/help/\n────────────────────────────────\n◆このメールについてのお問い合わせはこちらへ\n電話番号: 0570-099-033 （ナビダイヤル）\n自動音声ガイダンスで「1」を押してください。\n----------------------------------------------------------------\n午前9時～午後6時（土・日・祝日も受付）\n────────────────────────────────\n\n",
