      "subCatKey": null,
      "subCategory": "",
      "title": "【第3弾】甲子園開幕前（2026年8月3日,4日）",
      "subject": "※重要※【NHK ONE】アカウント移行のお願い～9/30まで",
      "body": "────────────────────────────────\n ※このメールは、旧NHKプラスにご登録いただいていた方のうち、2026年７月３１日時点で「NHK ONE」へのアカウント移行手続きがお済みでない方へ、送信専用アドレスからお送りしています。\n────────────────────────────────\nいつもNHKをご利用いただき、誠にありがとうございます。\n\nこれまでも何度か御案内してきましたが、NHKONEでは、旧NHKプラスをご利用いただいていたお客様向けに、簡単にお手続きいただける「アカウント移行手続き」をご用意しております。\nNHK ONEへの移行手続きの期限は２０２６年9月30日です。\n期限まで残りわずかとなっておりますので、まだお手続きがお済みでない場合は、お早めにご対応くださいますようお願いいたします。\n\n＜移行手続きはこちら＞\n https://portal.web.nhk/kakunin\n※お手続きにかかる時間は、5～10分程度です。\n\n＜手続き方法の詳しいご案内＞\n https://www.nhk.or.jp/nhkone/how-to-use/article/P001-0001/\n\nNHK ONEでは、「連続テレビ小説（朝ドラ）」や「大河ドラマ」をはじめ、さまざまな番組やニュースを、同時配信や放送後１週間の見逃し配信パソコンやスマートフォンなどでご覧いただけます。\nまもなく開幕する第１０８回全国高校野球選手権大会（夏の甲子園・８月５日開幕）も「NHK ONE」でお楽しみいただけます。\n\nぜひこの機会に移行手続きをお済ませいただき、引き続きNHKのサービスをお楽しみいただけますと幸いです。\n\n\n※すでに移行手続きがお済みの場合は、行き違いでのご案内となりましたことをお詫び申し上げます。\n※移行手続き前に受信契約を解約された方にも、このメールが配信される場合があります。あらかじめご了承ください。\n※NHKを名乗る不審なメールが確認されています。移行手続きは必ず上記のNHK公式サイトからお願いいたします。\n\n今後ともNHKへのご理解とご協力を賜りますよう、よろしくお願い申し上げます。\n\n────────────────────────────────\n◆「NHK ONE」に関するよくあるご質問\n https://www.nhk.or.jp/nhkone/help/\n────────────────────────────────\n◆このメールについてのお問い合わせ\n 電話番号：0570-099-033（ナビダイヤル）\n 自動音声ガイダンスで「1」を押してください。\n 午前9時～午後6時（土・日・祝日も受付）\n────────────────────────────────\n",
      "note": "甲子園開幕前（８月３，４日）",
